def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform separator row or column.
    sep = None
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            sep = ("v", c)
            break
    if sep is None:
        for r in range(h):
            if len(set(grid[r])) == 1:
                sep = ("h", r)
                break

    if sep[0] == "v":
        c = sep[1]
        left = [row[:c] for row in grid]
        right = [row[c + 1:] for row in grid]
    else:
        r = sep[1]
        left = grid[:r]
        right = grid[r + 1:]

    from collections import Counter
    allvals = Counter(v for row in left for v in row)
    bg = allvals.most_common(1)[0][0]
    mark = next(v for v, _ in allvals.most_common() if v != bg)

    rightvals = Counter(v for row in right for v in row)
    rbg = rightvals.most_common(1)[0][0]
    rmark = next(v for v, _ in rightvals.most_common() if v != rbg)

    return [
        [3 if left[y][x] == mark and right[y][x] != rmark else 4
         for x in range(len(left[0]))]
        for y in range(len(left))
    ]
